      WHEN 'a' THEN 'A'
      WHEN 'b' THEN 'B'
      WHEN 'c' THEN 'C'
      ELSE NULLIF(trim(`abc_classification`), '')
    END AS `abc_classification`,
    COALESCE(try_to_timestamp(trim(`approval_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`approval_timestamp`) AS TIMESTAMP)) AS `approval_timestamp`,
    TRY_CAST(NULLIF(trim(`approved_safety_stock_units`), '') AS DECIMAL(15,3)) AS `approved_safety_stock_units`,
    TRY_CAST(NULLIF(trim(`average_daily_demand_units`), '') AS DECIMAL(15,3)) AS `average_daily_demand_units`,
    TRY_CAST(NULLIF(trim(`average_lead_time_days`), '') AS DECIMAL(8,2)) AS `average_lead_time_days`,
    TRY_CAST(NULLIF(trim(`calculated_safety_stock_units`), '') AS DECIMAL(15,3)) AS `calculated_safety_stock_units`,
    CASE lower(trim(`calculation_method`))
      WHEN 'statistical' THEN 'statistical'
      WHEN 'days_of_supply' THEN 'days_of_supply'
      WHEN 'manual_override' THEN 'manual_override'
      WHEN 'service_level_based' THEN 'service_level_based'
      WHEN 'lead_time_based' THEN 'lead_time_based'
      WHEN 'hybrid' THEN 'hybrid'
      ELSE NULLIF(trim(`calculation_method`), '')
    END AS `calculation_method`,
    COALESCE(try_to_timestamp(trim(`calculation_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`calculation_timestamp`) AS TIMESTAMP)) AS `calculation_timestamp`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    TRY_CAST(NULLIF(trim(`days_of_supply_target`), '') AS DECIMAL(6,2)) AS `days_of_supply_target`,
    CASE lower(trim(`demand_classification`))
      WHEN 'steady' THEN 'steady'
      WHEN 'seasonal' THEN 'seasonal'
      WHEN 'erratic' THEN 'erratic'
      WHEN 'lumpy' THEN 'lumpy'
      WHEN 'intermittent' THEN 'intermittent'
      WHEN 'obsolete' THEN 'obsolete'
      ELSE NULLIF(trim(`demand_classification`), '')
    END AS `demand_classification`,
    TRY_CAST(NULLIF(trim(`demand_variability_coefficient`), '') AS DECIMAL(10,4)) AS `demand_variability_coefficient`,
    COALESCE(try_to_date(trim(`effective_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_date`) AS DATE)) AS `effective_date`,
    COALESCE(try_to_date(trim(`expiration_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiration_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiration_date`) AS DATE)) AS `expiration_date`,
    TRY_CAST(NULLIF(trim(`forecast_accuracy_percent`), '') AS DECIMAL(5,2)) AS `forecast_accuracy_percent`,
    TRY_CAST(NULLIF(trim(`holding_cost_per_unit`), '') AS DECIMAL(15,4)) AS `holding_cost_per_unit`,
    CASE WHEN lower(trim(`is_active`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_active`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_active`,
    COALESCE(try_to_timestamp(trim(`last_review_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_review_timestamp`) AS TIMESTAMP)) AS `last_review_timestamp`,
    TRY_CAST(NULLIF(trim(`lead_time_variability_days`), '') AS DECIMAL(8,2)) AS `lead_time_variability_days`,
    TRY_CAST(NULLIF(trim(`minimum_order_quantity`), '') AS DECIMAL(15,3)) AS `minimum_order_quantity`,
    COALESCE(try_to_timestamp(trim(`modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`modified_timestamp`) AS TIMESTAMP)) AS `modified_timestamp`,
    COALESCE(try_to_date(trim(`next_review_date`), 'yyyy-MM-dd'), try_to_date(trim(`next_review_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`next_review_date`) AS DATE)) AS `next_review_date`,
    TRY_CAST(NULLIF(trim(`order_multiple`), '') AS DECIMAL(15,3)) AS `order_multiple`,
    NULLIF(trim(`override_notes`), '') AS `override_notes`,
    CASE lower(trim(`override_reason_code`))
      WHEN 'promotional_event' THEN 'promotional_event'
      WHEN 'seasonal_peak' THEN 'seasonal_peak'
      WHEN 'supply_risk' THEN 'supply_risk'
      WHEN 'new_product_launch' THEN 'new_product_launch'
      WHEN 'phase_out' THEN 'phase_out'
      WHEN 'quality_issue' THEN 'quality_issue'
      ELSE NULLIF(trim(`override_reason_code`), '')
    END AS `override_reason_code`,
    COALESCE(try_to_date(trim(`planning_period_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`planning_period_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`planning_period_end_date`) AS DATE)) AS `planning_period_end_date`,
    COALESCE(try_to_date(trim(`planning_period_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`planning_period_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`planning_period_start_date`) AS DATE)) AS `planning_period_start_date`,
    CASE lower(trim(`review_status`))
      WHEN 'pending_review' THEN 'pending_review'
      WHEN 'approved' THEN 'approved'
      WHEN 'rejected' THEN 'rejected'
      WHEN 'under_revision' THEN 'under_revision'
      WHEN 'expired' THEN 'expired'
      ELSE NULLIF(trim(`review_status`), '')
    END AS `review_status`,
    TRY_CAST(NULLIF(trim(`shelf_life_days`), '') AS INT) AS `shelf_life_days`,
    TRY_CAST(NULLIF(trim(`stockout_cost_per_unit`), '') AS DECIMAL(15,4)) AS `stockout_cost_per_unit`,
    TRY_CAST(NULLIF(trim(`supply_risk_score`), '') AS DECIMAL(5,2)) AS `supply_risk_score`,
    TRY_CAST(NULLIF(trim(`target_service_level_percent`), '') AS DECIMAL(5,2)) AS `target_service_level_percent`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    CASE lower(trim(`xyz_classification`))
      WHEN 'x' THEN 'X'
      WHEN 'y' THEN 'Y'
      WHEN 'z' THEN 'Z'
      ELSE NULLIF(trim(`xyz_classification`), '')
    END AS `xyz_classification`,
    TRY_CAST(NULLIF(trim(`z_score`), '') AS DECIMAL(6,4)) AS `z_score`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.supply_safety_stock
)
SELECT *
FROM typed
QUALIFY `safety_stock_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `safety_stock_id` ORDER BY `modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- supply.replenishment_order ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.supply_replenishment_order (
  CONSTRAINT `replenishment_order_id_not_null` EXPECT (`replenishment_order_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: supply.replenishment_order typed and cleaned, one row per replenishment_order_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`replenishment_order_id`), '') AS BIGINT) AS `replenishment_order_id`,
    TRY_CAST(NULLIF(trim(`consensus_demand_id`), '') AS BIGINT) AS `consensus_demand_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`demand_plan_id`), '') AS BIGINT) AS `demand_plan_id`,
    TRY_CAST(NULLIF(trim(`destination_location_supply_network_node_id`), '') AS BIGINT) AS `destination_location_supply_network_node_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`inbound_receipt_id`), '') AS BIGINT) AS `inbound_receipt_id`,
    TRY_CAST(NULLIF(trim(`inventory_policy_id`), '') AS BIGINT) AS `inventory_policy_id`,
    TRY_CAST(NULLIF(trim(`network_lane_id`), '') AS BIGINT) AS `network_lane_id`,
    TRY_CAST(NULLIF(trim(`primary_supply_network_node_id`), '') AS BIGINT) AS `primary_supply_network_node_id`,
    TRY_CAST(NULLIF(trim(`production_order_id`), '') AS BIGINT) AS `production_order_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`purchase_order_id`), '') AS BIGINT) AS `purchase_order_id`,
    TRY_CAST(NULLIF(trim(`safety_stock_id`), '') AS BIGINT) AS `safety_stock_id`,
    TRY_CAST(NULLIF(trim(`shipment_id`), '') AS BIGINT) AS `shipment_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`sop_cycle_id`), '') AS BIGINT) AS `sop_cycle_id`,
    TRY_CAST(NULLIF(trim(`supplier_contract_id`), '') AS BIGINT) AS `supplier_contract_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    COALESCE(try_to_date(trim(`actual_receipt_date`), 'yyyy-MM-dd'), try_to_date(trim(`actual_receipt_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`actual_receipt_date`) AS DATE)) AS `actual_receipt_date`,
    COALESCE(try_to_date(trim(`actual_ship_date`), 'yyyy-MM-dd'), try_to_date(trim(`actual_ship_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`actual_ship_date`) AS DATE)) AS `actual_ship_date`,
    TRY_CAST(NULLIF(trim(`available_to_promise_quantity`), '') AS DECIMAL(18,3)) AS `available_to_promise_quantity`,
    NULLIF(trim(`cancellation_reason`), '') AS `cancellation_reason`,
    TRY_CAST(NULLIF(trim(`confirmed_quantity`), '') AS DECIMAL(18,3)) AS `confirmed_quantity`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    COALESCE(try_to_timestamp(trim(`drp_run_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`drp_run_timestamp`) AS TIMESTAMP)) AS `drp_run_timestamp`,
    TRY_CAST(NULLIF(trim(`forecast_demand_quantity`), '') AS DECIMAL(18,3)) AS `forecast_demand_quantity`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    TRY_CAST(NULLIF(trim(`order_cost_amount`), '') AS DECIMAL(18,2)) AS `order_cost_amount`,
    NULLIF(trim(`order_notes`), '') AS `order_notes`,
    CASE lower(trim(`order_status`))
      WHEN 'draft' THEN 'draft'
      WHEN 'open' THEN 'open'
      WHEN 'in_transit' THEN 'in_transit'
      WHEN 'received' THEN 'received'
      WHEN 'cancelled' THEN 'cancelled'
      WHEN 'closed' THEN 'closed'
      ELSE NULLIF(trim(`order_status`), '')
    END AS `order_status`,
    CASE lower(trim(`order_type`))
      WHEN 'planned' THEN 'planned'
      WHEN 'firmed' THEN 'firmed'
      WHEN 'released' THEN 'released'
      ELSE NULLIF(trim(`order_type`), '')
    END AS `order_type`,
    COALESCE(try_to_date(trim(`planned_receipt_date`), 'yyyy-MM-dd'), try_to_date(trim(`planned_receipt_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`planned_receipt_date`) AS DATE)) AS `planned_receipt_date`,
    COALESCE(try_to_date(trim(`planned_ship_date`), 'yyyy-MM-dd'), try_to_date(trim(`planned_ship_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`planned_ship_date`) AS DATE)) AS `planned_ship_date`,
    CASE lower(trim(`priority_code`))
      WHEN 'critical' THEN 'critical'
      WHEN 'high' THEN 'high'
      WHEN 'normal' THEN 'normal'
      WHEN 'low' THEN 'low'
      ELSE NULLIF(trim(`priority_code`), '')
    END AS `priority_code`,
    TRY_CAST(NULLIF(trim(`received_quantity`), '') AS DECIMAL(18,3)) AS `received_quantity`,
    NULLIF(trim(`replenishment_order_number`), '') AS `replenishment_order_number`,
    TRY_CAST(NULLIF(trim(`requested_quantity`), '') AS DECIMAL(18,3)) AS `requested_quantity`,
    CASE WHEN lower(trim(`safety_stock_trigger_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`safety_stock_trigger_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `safety_stock_trigger_flag`,
    TRY_CAST(NULLIF(trim(`shipped_quantity`), '') AS DECIMAL(18,3)) AS `shipped_quantity`,
    TRY_CAST(NULLIF(trim(`transit_lead_time_days`), '') AS INT) AS `transit_lead_time_days`,
    CASE lower(trim(`transportation_mode`))
      WHEN 'truck' THEN 'truck'
      WHEN 'rail' THEN 'rail'
      WHEN 'air' THEN 'air'
      WHEN 'ocean' THEN 'ocean'
      WHEN 'intermodal' THEN 'intermodal'
      ELSE NULLIF(trim(`transportation_mode`), '')
    END AS `transportation_mode`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.supply_replenishment_order
)
SELECT *
FROM typed
QUALIFY `replenishment_order_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `replenishment_order_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- supply.network_node ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.supply_network_node (
  CONSTRAINT `network_node_id_not_null` EXPECT (`network_node_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: supply.network_node typed and cleaned, one row per network_node_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`network_node_id`), '') AS BIGINT) AS `network_node_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`distribution_facility_id`), '') AS BIGINT) AS `distribution_facility_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    NULLIF(trim(`address_line_1`), '') AS `address_line_1`,
    NULLIF(trim(`address_line_2`), '') AS `address_line_2`,
    CASE lower(trim(`capacity_class`))
      WHEN 'small' THEN 'small'
      WHEN 'medium' THEN 'medium'
      WHEN 'large' THEN 'large'
      WHEN 'extra_large' THEN 'extra_large'
      WHEN 'mega' THEN 'mega'
      ELSE NULLIF(trim(`capacity_class`), '')
    END AS `capacity_class`,
    NULLIF(trim(`city`), '') AS `city`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    CASE WHEN lower(trim(`cross_dock_enabled_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`cross_dock_enabled_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `cross_dock_enabled_flag`,
    CASE WHEN lower(trim(`dsd_enabled_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`dsd_enabled_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `dsd_enabled_flag`,
    COALESCE(try_to_date(trim(`effective_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_end_date`) AS DATE)) AS `effective_end_date`,
    COALESCE(try_to_date(trim(`effective_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_start_date`) AS DATE)) AS `effective_start_date`,
    NULLIF(trim(`gln`), '') AS `gln`,
    CASE WHEN lower(trim(`hazmat_certified_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`hazmat_certified_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `hazmat_certified_flag`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    TRY_CAST(NULLIF(trim(`latitude`), '') AS DECIMAL(10,7)) AS `latitude`,
    TRY_CAST(NULLIF(trim(`lead_time_days`), '') AS INT) AS `lead_time_days`,
    TRY_CAST(NULLIF(trim(`longitude`), '') AS DECIMAL(10,7)) AS `longitude`,
    NULLIF(trim(`node_code`), '') AS `node_code`,
    NULLIF(trim(`node_name`), '') AS `node_name`,
    CASE lower(trim(`node_status`))
      WHEN 'active' THEN 'active'
      WHEN 'inactive' THEN 'inactive'
      WHEN 'planned' THEN 'planned'
      WHEN 'decommissioned' THEN 'decommissioned'
      WHEN 'temporarily_closed' THEN 'temporarily_closed'
      ELSE NULLIF(trim(`node_status`), '')
    END AS `node_status`,
    NULLIF(trim(`node_type`), '') AS `node_type`,
    CASE lower(trim(`ownership_type`))
      WHEN 'owned' THEN 'owned'
      WHEN 'leased' THEN 'leased'
      WHEN '3pl_managed' THEN '3pl_managed'
      WHEN 'co_manufacturer' THEN 'co_manufacturer'
      WHEN 'contract' THEN 'contract'
      ELSE NULLIF(trim(`ownership_type`), '')
    END AS `ownership_type`,
    NULLIF(trim(`planning_group`), '') AS `planning_group`,
    NULLIF(trim(`postal_code`), '') AS `postal_code`,
    CASE lower(trim(`replenishment_frequency`))
      WHEN 'daily' THEN 'daily'
      WHEN 'weekly' THEN 'weekly'
      WHEN 'biweekly' THEN 'biweekly'
      WHEN 'monthly' THEN 'monthly'
      WHEN 'on_demand' THEN 'on_demand'
      ELSE NULLIF(trim(`replenishment_frequency`), '')
    END AS `replenishment_frequency`,
    TRY_CAST(NULLIF(trim(`safety_stock_days`), '') AS INT) AS `safety_stock_days`,
    TRY_CAST(NULLIF(trim(`sourcing_priority`), '') AS INT) AS `sourcing_priority`,
    NULLIF(trim(`state_province`), '') AS `state_province`,
    TRY_CAST(NULLIF(trim(`storage_capacity_units`), '') AS DECIMAL(15,2)) AS `storage_capacity_units`,
    CASE lower(trim(`storage_capacity_uom`))
      WHEN 'pallets' THEN 'pallets'
      WHEN 'cases' THEN 'cases'
      WHEN 'cubic_meters' THEN 'cubic_meters'
      WHEN 'square_meters' THEN 'square_meters'
      ELSE NULLIF(trim(`storage_capacity_uom`), '')
    END AS `storage_capacity_uom`,
    CASE WHEN lower(trim(`temperature_controlled_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`temperature_controlled_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `temperature_controlled_flag`,
    TRY_CAST(NULLIF(trim(`throughput_capacity_daily`), '') AS DECIMAL(15,2)) AS `throughput_capacity_daily`,
    CASE lower(trim(`throughput_capacity_uom`))
      WHEN 'cases_per_day' THEN 'cases_per_day'
      WHEN 'pallets_per_day' THEN 'pallets_per_day'
      WHEN 'units_per_day' THEN 'units_per_day'
      WHEN 'tons_per_day' THEN 'tons_per_day'
      ELSE NULLIF(trim(`throughput_capacity_uom`), '')
    END AS `throughput_capacity_uom`,
    NULLIF(trim(`time_zone`), '') AS `time_zone`,
    CASE WHEN lower(trim(`vmi_enabled_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`vmi_enabled_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `vmi_enabled_flag`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.supply_network_node
)
SELECT *
FROM typed
QUALIFY `network_node_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `network_node_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- supply.network_lane ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.supply_network_lane (
  CONSTRAINT `network_lane_id_not_null` EXPECT (`network_lane_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: supply.network_lane typed and cleaned, one row per network_lane_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`network_lane_id`), '') AS BIGINT) AS `network_lane_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`destination_location_supply_network_node_id`), '') AS BIGINT) AS `destination_location_supply_network_node_id`,
    TRY_CAST(NULLIF(trim(`primary_supply_network_node_id`), '') AS BIGINT) AS `primary_supply_network_node_id`,
    TRY_CAST(NULLIF(trim(`supplier_contract_id`), '') AS BIGINT) AS `supplier_contract_id`,
    TRY_CAST(NULLIF(trim(`supplier_id`), '') AS BIGINT) AS `supplier_id`,
    TRY_CAST(NULLIF(trim(`capacity_quantity`), '') AS DECIMAL(18,3)) AS `capacity_quantity`,
    NULLIF(trim(`capacity_uom`), '') AS `capacity_uom`,
    NULLIF(trim(`compliance_requirements`), '') AS `compliance_requirements`,
    TRY_CAST(NULLIF(trim(`cost_per_unit`), '') AS DECIMAL(18,4)) AS `cost_per_unit`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    COALESCE(try_to_date(trim(`effective_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_end_date`) AS DATE)) AS `effective_end_date`,
    COALESCE(try_to_date(trim(`effective_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_start_date`) AS DATE)) AS `effective_start_date`,
    CASE WHEN lower(trim(`is_active`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_active`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_active`,
    CASE WHEN lower(trim(`is_primary_lane`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`is_primary_lane`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `is_primary_lane`,
    NULLIF(trim(`lane_code`), '') AS `lane_code`,
    NULLIF(trim(`lane_name`), '') AS `lane_name`,
    CASE lower(trim(`lane_type`))
      WHEN 'production' THEN 'production'
      WHEN 'transfer' THEN 'transfer'
      WHEN 'external_procurement' THEN 'external_procurement'
      WHEN 'direct_shipment' THEN 'direct_shipment'
      WHEN 'cross_dock' THEN 'cross_dock'
      WHEN 'drop_ship' THEN 'drop_ship'
      ELSE NULLIF(trim(`lane_type`), '')
    END AS `lane_type`,
    NULLIF(trim(`last_modified_by`), '') AS `last_modified_by`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    TRY_CAST(NULLIF(trim(`lot_size_quantity`), '') AS DECIMAL(18,3)) AS `lot_size_quantity`,
    TRY_CAST(NULLIF(trim(`maximum_order_quantity`), '') AS DECIMAL(18,3)) AS `maximum_order_quantity`,
    TRY_CAST(NULLIF(trim(`minimum_order_quantity`), '') AS DECIMAL(18,3)) AS `minimum_order_quantity`,
    CASE lower(trim(`network_lane_status`))
      WHEN 'active' THEN 'active'
      WHEN 'inactive' THEN 'inactive'
      WHEN 'suspended' THEN 'suspended'
      WHEN 'planned' THEN 'planned'
      WHEN 'decommissioned' THEN 'decommissioned'
      ELSE NULLIF(trim(`network_lane_status`), '')
    END AS `network_lane_status`,
    NULLIF(trim(`notes`), '') AS `notes`,
    TRY_CAST(NULLIF(trim(`otif_target_pct`), '') AS DECIMAL(5,2)) AS `otif_target_pct`,
    NULLIF(trim(`planning_group`), '') AS `planning_group`,
    TRY_CAST(NULLIF(trim(`processing_lead_time_days`), '') AS DECIMAL(10,2)) AS `processing_lead_time_days`,
    CASE lower(trim(`risk_category`))
      WHEN 'low' THEN 'low'
      WHEN 'medium' THEN 'medium'
      WHEN 'high' THEN 'high'
      WHEN 'critical' THEN 'critical'
      ELSE NULLIF(trim(`risk_category`), '')
    END AS `risk_category`,
    TRY_CAST(NULLIF(trim(`safety_stock_days`), '') AS DECIMAL(10,2)) AS `safety_stock_days`,
    TRY_CAST(NULLIF(trim(`service_level_target_pct`), '') AS DECIMAL(5,2)) AS `service_level_target_pct`,
    TRY_CAST(NULLIF(trim(`sourcing_priority`), '') AS INT) AS `sourcing_priority`,
    TRY_CAST(NULLIF(trim(`standard_lead_time_days`), '') AS DECIMAL(10,2)) AS `standard_lead_time_days`,
    TRY_CAST(NULLIF(trim(`transportation_lead_time_days`), '') AS DECIMAL(10,2)) AS `transportation_lead_time_days`,
    CASE lower(trim(`transportation_mode`))
      WHEN 'truck' THEN 'truck'
      WHEN 'rail' THEN 'rail'
      WHEN 'ocean' THEN 'ocean'
      WHEN 'air' THEN 'air'
      WHEN 'intermodal' THEN 'intermodal'
      WHEN 'parcel' THEN 'parcel'
      ELSE NULLIF(trim(`transportation_mode`), '')
    END AS `transportation_mode`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.supply_network_lane
)
SELECT *
FROM typed
QUALIFY `network_lane_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `network_lane_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- supply.atp_record ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.supply_atp_record (
  CONSTRAINT `atp_record_id_not_null` EXPECT (`atp_record_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: supply.atp_record typed and cleaned, one row per atp_record_id (latest updated_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`atp_record_id`), '') AS BIGINT) AS `atp_record_id`,
    TRY_CAST(NULLIF(trim(`consensus_demand_id`), '') AS BIGINT) AS `consensus_demand_id`,
    TRY_CAST(NULLIF(trim(`demand_plan_id`), '') AS BIGINT) AS `demand_plan_id`,
    TRY_CAST(NULLIF(trim(`inventory_policy_id`), '') AS BIGINT) AS `inventory_policy_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`production_order_id`), '') AS BIGINT) AS `production_order_id`,
    TRY_CAST(NULLIF(trim(`purchase_order_id`), '') AS BIGINT) AS `purchase_order_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`sop_cycle_id`), '') AS BIGINT) AS `sop_cycle_id`,
    TRY_CAST(NULLIF(trim(`supply_network_node_id`), '') AS BIGINT) AS `supply_network_node_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    TRY_CAST(NULLIF(trim(`allocated_quantity`), '') AS DECIMAL(18,3)) AS `allocated_quantity`,
    CASE lower(trim(`atp_calculation_method`))
      WHEN 'simple' THEN 'simple'
      WHEN 'cumulative' THEN 'cumulative'
      WHEN 'multi_level' THEN 'multi_level'
      WHEN 'product_allocation' THEN 'product_allocation'
      ELSE NULLIF(trim(`atp_calculation_method`), '')
    END AS `atp_calculation_method`,
    TRY_CAST(NULLIF(trim(`atp_check_horizon_days`), '') AS INT) AS `atp_check_horizon_days`,
    NULLIF(trim(`atp_confirmation_number`), '') AS `atp_confirmation_number`,
    COALESCE(try_to_date(trim(`atp_date`), 'yyyy-MM-dd'), try_to_date(trim(`atp_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`atp_date`) AS DATE)) AS `atp_date`,
    TRY_CAST(NULLIF(trim(`atp_quantity`), '') AS DECIMAL(18,3)) AS `atp_quantity`,
    CASE lower(trim(`atp_status`))
      WHEN 'available' THEN 'available'
      WHEN 'constrained' THEN 'constrained'
      WHEN 'blocked' THEN 'blocked'
      WHEN 'expired' THEN 'expired'
      ELSE NULLIF(trim(`atp_status`), '')
    END AS `atp_status`,
    TRY_CAST(NULLIF(trim(`backorder_quantity`), '') AS DECIMAL(18,3)) AS `backorder_quantity`,
    COALESCE(try_to_timestamp(trim(`calculation_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`calculation_timestamp`) AS TIMESTAMP)) AS `calculation_timestamp`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    TRY_CAST(NULLIF(trim(`ctp_quantity`), '') AS DECIMAL(18,3)) AS `ctp_quantity`,
    TRY_CAST(NULLIF(trim(`cumulative_atp_quantity`), '') AS DECIMAL(18,3)) AS `cumulative_atp_quantity`,
    CASE lower(trim(`customer_priority_tier`))
      WHEN 'tier_1' THEN 'tier_1'
      WHEN 'tier_2' THEN 'tier_2'
      WHEN 'tier_3' THEN 'tier_3'
      WHEN 'standard' THEN 'standard'
      ELSE NULLIF(trim(`customer_priority_tier`), '')
    END AS `customer_priority_tier`,
    NULLIF(trim(`demand_pegging_reference`), '') AS `demand_pegging_reference`,
    COALESCE(try_to_date(trim(`expiration_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiration_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiration_date`) AS DATE)) AS `expiration_date`,
    TRY_CAST(NULLIF(trim(`forecast_consumption_quantity`), '') AS DECIMAL(18,3)) AS `forecast_consumption_quantity`,
    TRY_CAST(NULLIF(trim(`intransit_quantity`), '') AS DECIMAL(18,3)) AS `intransit_quantity`,
    TRY_CAST(NULLIF(trim(`minimum_shelf_life_days`), '') AS INT) AS `minimum_shelf_life_days`,
    TRY_CAST(NULLIF(trim(`on_hand_inventory`), '') AS DECIMAL(18,3)) AS `on_hand_inventory`,
    TRY_CAST(NULLIF(trim(`planned_receipt_quantity`), '') AS DECIMAL(18,3)) AS `planned_receipt_quantity`,
    NULLIF(trim(`planning_version`), '') AS `planning_version`,
    NULLIF(trim(`product_allocation_group`), '') AS `product_allocation_group`,
    TRY_CAST(NULLIF(trim(`production_order_quantity`), '') AS DECIMAL(18,3)) AS `production_order_quantity`,
    TRY_CAST(NULLIF(trim(`purchase_order_quantity`), '') AS DECIMAL(18,3)) AS `purchase_order_quantity`,
    TRY_CAST(NULLIF(trim(`safety_stock_quantity`), '') AS DECIMAL(18,3)) AS `safety_stock_quantity`,
    NULLIF(trim(`source_system_record_code`), '') AS `source_system_record_code`,
    NULLIF(trim(`supply_pegging_reference`), '') AS `supply_pegging_reference`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    COALESCE(try_to_timestamp(trim(`updated_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`updated_timestamp`) AS TIMESTAMP)) AS `updated_timestamp`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.supply_atp_record
)
SELECT *
FROM typed
QUALIFY `atp_record_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `atp_record_id` ORDER BY `updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- supply.sop_cycle ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.supply_sop_cycle (
  CONSTRAINT `sop_cycle_id_not_null` EXPECT (`sop_cycle_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: supply.sop_cycle typed and cleaned, one row per sop_cycle_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`sop_cycle_id`), '') AS BIGINT) AS `sop_cycle_id`,
    TRY_CAST(NULLIF(trim(`baseline_demand_volume`), '') AS DECIMAL(18,2)) AS `baseline_demand_volume`,
    TRY_CAST(NULLIF(trim(`consensus_demand_volume`), '') AS DECIMAL(18,2)) AS `consensus_demand_volume`,
    TRY_CAST(NULLIF(trim(`constrained_supply_volume`), '') AS DECIMAL(18,2)) AS `constrained_supply_volume`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`cycle_code`), '') AS `cycle_code`,
    COALESCE(try_to_date(trim(`cycle_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`cycle_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`cycle_end_date`) AS DATE)) AS `cycle_end_date`,
    COALESCE(try_to_date(trim(`cycle_locked_date`), 'yyyy-MM-dd'), try_to_date(trim(`cycle_locked_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`cycle_locked_date`) AS DATE)) AS `cycle_locked_date`,
    CASE WHEN lower(trim(`cycle_locked_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`cycle_locked_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `cycle_locked_flag`,
    NULLIF(trim(`cycle_name`), '') AS `cycle_name`,
    NULLIF(trim(`cycle_notes`), '') AS `cycle_notes`,
    CASE lower(trim(`cycle_phase`))
      WHEN 'statistical_forecast' THEN 'statistical_forecast'
      WHEN 'demand_review' THEN 'demand_review'
      WHEN 'supply_review' THEN 'supply_review'
      WHEN 'pre_sop' THEN 'pre_sop'
      WHEN 'executive_sop' THEN 'executive_sop'
      WHEN 'closed' THEN 'closed'
      ELSE NULLIF(trim(`cycle_phase`), '')
    END AS `cycle_phase`,
    COALESCE(try_to_date(trim(`cycle_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`cycle_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`cycle_start_date`) AS DATE)) AS `cycle_start_date`,
    CASE lower(trim(`cycle_type`))
      WHEN 'monthly' THEN 'monthly'
      WHEN 'quarterly' THEN 'quarterly'
      WHEN 'annual' THEN 'annual'
      WHEN 'rolling' THEN 'rolling'
      WHEN 'event_driven' THEN 'event_driven'
      ELSE NULLIF(trim(`cycle_type`), '')
    END AS `cycle_type`,
    CASE WHEN lower(trim(`demand_consensus_achieved_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`demand_consensus_achieved_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `demand_consensus_achieved_flag`,
    COALESCE(try_to_date(trim(`demand_review_due_date`), 'yyyy-MM-dd'), try_to_date(trim(`demand_review_due_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`demand_review_due_date`) AS DATE)) AS `demand_review_due_date`,
    COALESCE(try_to_date(trim(`executive_approval_date`), 'yyyy-MM-dd'), try_to_date(trim(`executive_approval_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`executive_approval_date`) AS DATE)) AS `executive_approval_date`,
    CASE WHEN lower(trim(`executive_approval_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`executive_approval_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `executive_approval_flag`,
    NULLIF(trim(`executive_approval_notes`), '') AS `executive_approval_notes`,
    COALESCE(try_to_date(trim(`executive_sop_meeting_date`), 'yyyy-MM-dd'), try_to_date(trim(`executive_sop_meeting_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`executive_sop_meeting_date`) AS DATE)) AS `executive_sop_meeting_date`,
    TRY_CAST(NULLIF(trim(`fiscal_period`), '') AS INT) AS `fiscal_period`,
    TRY_CAST(NULLIF(trim(`fiscal_year`), '') AS INT) AS `fiscal_year`,
    TRY_CAST(NULLIF(trim(`frozen_period_months`), '') AS INT) AS `frozen_period_months`,
    NULLIF(trim(`key_assumptions`), '') AS `key_assumptions`,
    NULLIF(trim(`key_risks`), '') AS `key_risks`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    NULLIF(trim(`mitigation_actions`), '') AS `mitigation_actions`,
    CASE lower(trim(`phase_status`))
      WHEN 'not_started' THEN 'not_started'
      WHEN 'in_progress' THEN 'in_progress'
      WHEN 'completed' THEN 'completed'
      WHEN 'on_hold' THEN 'on_hold'
      WHEN 'cancelled' THEN 'cancelled'
      ELSE NULLIF(trim(`phase_status`), '')
    END AS `phase_status`,
    TRY_CAST(NULLIF(trim(`planning_horizon_months`), '') AS INT) AS `planning_horizon_months`,
    COALESCE(try_to_date(trim(`planning_month`), 'yyyy-MM-dd'), try_to_date(trim(`planning_month`), 'dd/MM/yyyy'), TRY_CAST(trim(`planning_month`) AS DATE)) AS `planning_month`,
    COALESCE(try_to_date(trim(`pre_sop_meeting_date`), 'yyyy-MM-dd'), try_to_date(trim(`pre_sop_meeting_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`pre_sop_meeting_date`) AS DATE)) AS `pre_sop_meeting_date`,
    COALESCE(try_to_date(trim(`statistical_forecast_due_date`), 'yyyy-MM-dd'), try_to_date(trim(`statistical_forecast_due_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`statistical_forecast_due_date`) AS DATE)) AS `statistical_forecast_due_date`,
    CASE WHEN lower(trim(`supply_consensus_achieved_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`supply_consensus_achieved_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `supply_consensus_achieved_flag`,
    TRY_CAST(NULLIF(trim(`supply_gap_volume`), '') AS DECIMAL(18,2)) AS `supply_gap_volume`,
    COALESCE(try_to_date(trim(`supply_review_due_date`), 'yyyy-MM-dd'), try_to_date(trim(`supply_review_due_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`supply_review_due_date`) AS DATE)) AS `supply_review_due_date`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.supply_sop_cycle
)
SELECT *
FROM typed
QUALIFY `sop_cycle_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `sop_cycle_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- supply.consensus_demand ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.supply_consensus_demand (
  CONSTRAINT `consensus_demand_id_not_null` EXPECT (`consensus_demand_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: supply.consensus_demand typed and cleaned, one row per consensus_demand_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`consensus_demand_id`), '') AS BIGINT) AS `consensus_demand_id`,
    TRY_CAST(NULLIF(trim(`demand_plan_id`), '') AS BIGINT) AS `demand_plan_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`forecast_version_id`), '') AS BIGINT) AS `forecast_version_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`sop_cycle_id`), '') AS BIGINT) AS `sop_cycle_id`,
    TRY_CAST(NULLIF(trim(`supply_network_node_id`), '') AS BIGINT) AS `supply_network_node_id`,
    TRY_CAST(NULLIF(trim(`trade_promotion_id`), '') AS BIGINT) AS `trade_promotion_id`,
    CASE WHEN lower(trim(`active_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`active_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `active_flag`,
    CASE lower(trim(`approval_status`))
      WHEN 'draft' THEN 'draft'
      WHEN 'submitted' THEN 'submitted'
      WHEN 'approved' THEN 'approved'
      WHEN 'rejected' THEN 'rejected'
      WHEN 'revised' THEN 'revised'
      ELSE NULLIF(trim(`approval_status`), '')
    END AS `approval_status`,
    COALESCE(try_to_timestamp(trim(`approval_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`approval_timestamp`) AS TIMESTAMP)) AS `approval_timestamp`,
    CASE lower(trim(`bias_indicator`))
      WHEN 'over_forecast' THEN 'over_forecast'
      WHEN 'under_forecast' THEN 'under_forecast'
      WHEN 'neutral' THEN 'neutral'
      ELSE NULLIF(trim(`bias_indicator`), '')
    END AS `bias_indicator`,
    NULLIF(trim(`comments`), '') AS `comments`,
    TRY_CAST(NULLIF(trim(`commercial_overlay_quantity`), '') AS DECIMAL(18,3)) AS `commercial_overlay_quantity`,
    CASE lower(trim(`confidence_level`))
      WHEN 'high' THEN 'high'
      WHEN 'medium' THEN 'medium'
      WHEN 'low' THEN 'low'
      ELSE NULLIF(trim(`confidence_level`), '')
    END AS `confidence_level`,
    TRY_CAST(NULLIF(trim(`consensus_quantity`), '') AS DECIMAL(18,3)) AS `consensus_quantity`,
    CASE WHEN lower(trim(`constrained_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`constrained_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `constrained_flag`,
    NULLIF(trim(`constraint_reason`), '') AS `constraint_reason`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    TRY_CAST(NULLIF(trim(`customer_commitment_quantity`), '') AS DECIMAL(18,3)) AS `customer_commitment_quantity`,
    CASE lower(trim(`demand_category`))
      WHEN 'base' THEN 'base'
      WHEN 'promotional' THEN 'promotional'
      WHEN 'seasonal' THEN 'seasonal'
      WHEN 'new_launch' THEN 'new_launch'
      WHEN 'phase_out' THEN 'phase_out'
      WHEN 'special_order' THEN 'special_order'
      ELSE NULLIF(trim(`demand_category`), '')
    END AS `demand_category`,
    NULLIF(trim(`demand_driver_code`), '') AS `demand_driver_code`,
    NULLIF(trim(`demand_driver_description`), '') AS `demand_driver_description`,
    TRY_CAST(NULLIF(trim(`demand_volatility_index`), '') AS DECIMAL(5,2)) AS `demand_volatility_index`,
    TRY_CAST(NULLIF(trim(`forecast_accuracy_previous_period`), '') AS DECIMAL(5,2)) AS `forecast_accuracy_previous_period`,
    NULLIF(trim(`forecast_model_code`), '') AS `forecast_model_code`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    COALESCE(try_to_date(trim(`last_review_date`), 'yyyy-MM-dd'), try_to_date(trim(`last_review_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`last_review_date`) AS DATE)) AS `last_review_date`,
    TRY_CAST(NULLIF(trim(`marketing_event_uplift_quantity`), '') AS DECIMAL(18,3)) AS `marketing_event_uplift_quantity`,
    TRY_CAST(NULLIF(trim(`new_product_launch_quantity`), '') AS DECIMAL(18,3)) AS `new_product_launch_quantity`,
    COALESCE(try_to_date(trim(`next_review_date`), 'yyyy-MM-dd'), try_to_date(trim(`next_review_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`next_review_date`) AS DATE)) AS `next_review_date`,
    CASE lower(trim(`planning_horizon_type`))
      WHEN 'short_term' THEN 'short_term'
      WHEN 'medium_term' THEN 'medium_term'
      WHEN 'long_term' THEN 'long_term'
      ELSE NULLIF(trim(`planning_horizon_type`), '')
    END AS `planning_horizon_type`,
    CASE WHEN lower(trim(`promotion_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`promotion_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `promotion_flag`,
    TRY_CAST(NULLIF(trim(`seasonality_factor`), '') AS DECIMAL(5,2)) AS `seasonality_factor`,
    TRY_CAST(NULLIF(trim(`statistical_forecast_quantity`), '') AS DECIMAL(18,3)) AS `statistical_forecast_quantity`,
    TRY_CAST(NULLIF(trim(`unconstrained_demand_quantity`), '') AS DECIMAL(18,3)) AS `unconstrained_demand_quantity`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    TRY_CAST(NULLIF(trim(`variance_percentage`), '') AS DECIMAL(5,2)) AS `variance_percentage`,
    TRY_CAST(NULLIF(trim(`variance_to_statistical`), '') AS DECIMAL(18,3)) AS `variance_to_statistical`,
    TRY_CAST(NULLIF(trim(`version_number`), '') AS INT) AS `version_number`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.supply_consensus_demand
)
SELECT *
FROM typed
QUALIFY `consensus_demand_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `consensus_demand_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- supply.sku_planning_param ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.supply_sku_planning_param (
  CONSTRAINT `sku_planning_param_id_not_null` EXPECT (`sku_planning_param_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: supply.sku_planning_param typed and cleaned, one row per sku_planning_param_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`sku_planning_param_id`), '') AS BIGINT) AS `sku_planning_param_id`,
    TRY_CAST(NULLIF(trim(`inspection_plan_id`), '') AS BIGINT) AS `inspection_plan_id`,
    TRY_CAST(NULLIF(trim(`inventory_policy_id`), '') AS BIGINT) AS `inventory_policy_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`supply_network_node_id`), '') AS BIGINT) AS `supply_network_node_id`,
    CASE lower(trim(`abc_classification`))
      WHEN 'a' THEN 'A'
      WHEN 'b' THEN 'B'
      WHEN 'c' THEN 'C'
      ELSE NULLIF(trim(`abc_classification`), '')
    END AS `abc_classification`,
    CASE WHEN lower(trim(`backorder_allowed_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`backorder_allowed_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `backorder_allowed_flag`,
    TRY_CAST(NULLIF(trim(`coverage_profile_days`), '') AS INT) AS `coverage_profile_days`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    CASE WHEN lower(trim(`critical_part_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`critical_part_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `critical_part_flag`,
    CASE lower(trim(`demand_pattern_type`))
      WHEN 'steady' THEN 'steady'
      WHEN 'seasonal' THEN 'seasonal'
      WHEN 'trending' THEN 'trending'
      WHEN 'intermittent' THEN 'intermittent'
      WHEN 'lumpy' THEN 'lumpy'
      WHEN 'erratic' THEN 'erratic'
      ELSE NULLIF(trim(`demand_pattern_type`), '')
    END AS `demand_pattern_type`,
    COALESCE(try_to_date(trim(`effective_end_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_end_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_end_date`) AS DATE)) AS `effective_end_date`,
    COALESCE(try_to_date(trim(`effective_start_date`), 'yyyy-MM-dd'), try_to_date(trim(`effective_start_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`effective_start_date`) AS DATE)) AS `effective_start_date`,
    TRY_CAST(NULLIF(trim(`fixed_lot_size_quantity`), '') AS DECIMAL(18,3)) AS `fixed_lot_size_quantity`,
    CASE lower(trim(`forecast_model_type`))
      WHEN 'moving_average' THEN 'moving_average'
      WHEN 'exponential_smoothing' THEN 'exponential_smoothing'
      WHEN 'holt_winters' THEN 'holt_winters'
      WHEN 'arima' THEN 'arima'
      WHEN 'machine_learning' THEN 'machine_learning'
      WHEN 'consensus' THEN 'consensus'
      ELSE NULLIF(trim(`forecast_model_type`), '')
    END AS `forecast_model_type`,
    TRY_CAST(NULLIF(trim(`goods_receipt_processing_time_days`), '') AS INT) AS `goods_receipt_processing_time_days`,
    CASE lower(trim(`inventory_valuation_method`))
      WHEN 'fifo' THEN 'fifo'
      WHEN 'fefo' THEN 'fefo'
      WHEN 'lifo' THEN 'lifo'
      WHEN 'weighted_average' THEN 'weighted_average'
      WHEN 'standard_cost' THEN 'standard_cost'
      ELSE NULLIF(trim(`inventory_valuation_method`), '')
    END AS `inventory_valuation_method`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    COALESCE(try_to_date(trim(`last_review_date`), 'yyyy-MM-dd'), try_to_date(trim(`last_review_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`last_review_date`) AS DATE)) AS `last_review_date`,
    CASE lower(trim(`lot_size_method`))
      WHEN 'fixed_lot_size' THEN 'fixed_lot_size'
      WHEN 'economic_order_quantity' THEN 'economic_order_quantity'
      WHEN 'lot_for_lot' THEN 'lot_for_lot'
      WHEN 'period_order_quantity' THEN 'period_order_quantity'
      WHEN 'weekly_lot_size' THEN 'weekly_lot_size'
      WHEN 'monthly_lot_size' THEN 'monthly_lot_size'
      ELSE NULLIF(trim(`lot_size_method`), '')
    END AS `lot_size_method`,
    TRY_CAST(NULLIF(trim(`maximum_order_quantity`), '') AS DECIMAL(18,3)) AS `maximum_order_quantity`,
    TRY_CAST(NULLIF(trim(`maximum_stock_level_quantity`), '') AS DECIMAL(18,3)) AS `maximum_stock_level_quantity`,
    TRY_CAST(NULLIF(trim(`minimum_order_quantity`), '') AS DECIMAL(18,3)) AS `minimum_order_quantity`,
    TRY_CAST(NULLIF(trim(`minimum_remaining_shelf_life_days`), '') AS INT) AS `minimum_remaining_shelf_life_days`,
    NULLIF(trim(`mrp_controller_code`), '') AS `mrp_controller_code`,
    CASE lower(trim(`mrp_type`))
      WHEN 'mrp' THEN 'mrp'
      WHEN 'reorder_point' THEN 'reorder_point'
      WHEN 'forecast_based' THEN 'forecast_based'
      WHEN 'time_phased' THEN 'time_phased'
      WHEN 'no_planning' THEN 'no_planning'
      ELSE NULLIF(trim(`mrp_type`), '')
    END AS `mrp_type`,
    COALESCE(try_to_date(trim(`next_review_date`), 'yyyy-MM-dd'), try_to_date(trim(`next_review_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`next_review_date`) AS DATE)) AS `next_review_date`,
    TRY_CAST(NULLIF(trim(`order_multiple_quantity`), '') AS DECIMAL(18,3)) AS `order_multiple_quantity`,
    NULLIF(trim(`parameter_notes`), '') AS `parameter_notes`,
    CASE lower(trim(`parameter_status`))
      WHEN 'active' THEN 'active'
      WHEN 'inactive' THEN 'inactive'
      WHEN 'pending_approval' THEN 'pending_approval'
      WHEN 'obsolete' THEN 'obsolete'
      ELSE NULLIF(trim(`parameter_status`), '')
    END AS `parameter_status`,
    TRY_CAST(NULLIF(trim(`planned_delivery_time_days`), '') AS INT) AS `planned_delivery_time_days`,
    NULLIF(trim(`planning_group`), '') AS `planning_group`,
    TRY_CAST(NULLIF(trim(`planning_horizon_days`), '') AS INT) AS `planning_horizon_days`,
    CASE lower(trim(`planning_strategy`))
      WHEN 'make_to_stock' THEN 'make_to_stock'
      WHEN 'make_to_order' THEN 'make_to_order'
      WHEN 'assemble_to_order' THEN 'assemble_to_order'
      WHEN 'engineer_to_order' THEN 'engineer_to_order'
      WHEN 'planning_without_final_assembly' THEN 'planning_without_final_assembly'
      ELSE NULLIF(trim(`planning_strategy`), '')
    END AS `planning_strategy`,
    TRY_CAST(NULLIF(trim(`planning_time_fence_days`), '') AS INT) AS `planning_time_fence_days`,
    CASE lower(trim(`procurement_type`))
      WHEN 'external_procurement' THEN 'external_procurement'
      WHEN 'in_house_production' THEN 'in_house_production'
      WHEN 'both' THEN 'both'
      WHEN 'subcontracting' THEN 'subcontracting'
      ELSE NULLIF(trim(`procurement_type`), '')
    END AS `procurement_type`,
    TRY_CAST(NULLIF(trim(`reorder_point_quantity`), '') AS DECIMAL(18,3)) AS `reorder_point_quantity`,
    NULLIF(trim(`rounding_profile_code`), '') AS `rounding_profile_code`,
    CASE lower(trim(`safety_stock_method`))
      WHEN 'fixed_quantity' THEN 'fixed_quantity'
      WHEN 'days_of_supply' THEN 'days_of_supply'
      WHEN 'dynamic_calculation' THEN 'dynamic_calculation'
      WHEN 'service_level_based' THEN 'service_level_based'
      ELSE NULLIF(trim(`safety_stock_method`), '')
    END AS `safety_stock_method`,
    NULLIF(trim(`seasonality_profile_code`), '') AS `seasonality_profile_code`,
    TRY_CAST(NULLIF(trim(`service_level_target_percent`), '') AS DECIMAL(5,2)) AS `service_level_target_percent`,
    TRY_CAST(NULLIF(trim(`shelf_life_days`), '') AS INT) AS `shelf_life_days`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    CASE lower(trim(`xyz_classification`))
      WHEN 'x' THEN 'X'
      WHEN 'y' THEN 'Y'
      WHEN 'z' THEN 'Z'
      ELSE NULLIF(trim(`xyz_classification`), '')
    END AS `xyz_classification`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.supply_sku_planning_param
)
SELECT *
FROM typed
QUALIFY `sku_planning_param_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `sku_planning_param_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;
